INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2889339', 'Australian frontier wars', 'The Australian frontier wars were the violent conflicts between Aboriginal Australians and White Australians (mostly those descended from British settlers) from the colonial period of Australia to at least 1928. The first conflict took place several months after the landing of the First Fleet in January 1788, and the last conflicts occurred in the early 20th century following the federation of the Australian colonies in 1901, with some occurring as late as 1934.', 1794, 9, 1, 1899, NULL, NULL, 'day', '1 September 1794 – 1899', 47, 'https://en.wikipedia.org/wiki/Australian_frontier_wars'),
  ('Q4353495', 'Castle Hill convict rebellion', 'The Castle Hill convict rebellion (also known as Battle of Vinegar Hill) was a convict rebellion in Castle Hill, Sydney, then part of the British colony of New South Wales. Led by veterans of the Irish Rebellion of 1798, the poorly armed insurgents confronted the colonial forces of Australia on 5 March 1804 at Rouse Hill.', 1804, 3, 5, 1804, 3, 5, 'day', '5 March 1804', 43, 'https://en.wikipedia.org/wiki/Castle_Hill_convict_rebellion'),
  ('Q2065299', 'Rum Rebellion', 'The Rum Rebellion of 1808 was a coup d''état in the British penal colony of New South Wales, staged by the New South Wales Corps in order to depose Governor William Bligh. Australia''s first and only military coup to date, its name derives from the illicit rum trade of early Sydney, over which the ''Rum Corps'', as it became known, maintained a monopoly.', 1808, 1, 26, 1810, 1, 1, 'day', '26 January 1808 – 1 January 1810', 51, 'https://en.wikipedia.org/wiki/Rum_Rebellion'),
  ('Q880629', 'Black War', 'The Black War was a period of violent conflict between British colonists and Aboriginal Tasmanians in Tasmania from the mid-1820s to 1832 which precipitated the near-extermination of the Indigenous population. The conflict was fought largely as a guerrilla war by both sides; some 600 to 900 Aboriginal Australians and more than 200 British colonists died.', 1820, NULL, NULL, 1832, NULL, NULL, 'decade', '1820s – 1832', 63, 'https://en.wikipedia.org/wiki/Black_War'),
  ('Q777916', 'Convincing Ground massacre', 'The Convincing Ground Massacre was a massacre of the Kilcarer gundidj clan of the Indigenous Gunditjmara people, by British whalers based at Portland Bay in south-eastern Australia. The massacre was part of the wider Eumeralla Wars between the British colonisers and Gunditjmara.', 1833, 3, 1, 1834, 3, 31, 'day', '1 March 1833 – 31 March 1834', 34, 'https://en.wikipedia.org/wiki/Convincing_Ground_massacre'),
  ('Q1550913', 'Pinjarra massacre', 'The Pinjarra massacre, in the past called the Battle of Pinjarra, occurred on 28 October 1834 in Pinjarra, Western Australia when a group of Bindjareb Noongar people were attacked by a detachment of 25 soldiers, police, and settlers led by Governor James Stirling. According to Stirling, "about 60 or 70" of the Bindjareb people were present at the camp and John Roe, who also participated, estimated about 70–80.', 1834, 10, 28, NULL, NULL, NULL, 'day', '28 October 1834', 39, 'https://en.wikipedia.org/wiki/Pinjarra_massacre'),
  ('Q810862', 'Batman''s Treaty', 'Batman''s Treaty was an agreement between the Port Phillip Association of British grazier colonists (represented by John Batman), and a group of Wurundjeri and Boonwurrung elders, for the purchase of land around Port Phillip, near the present site of Melbourne. The document came to be known as Batman''s Treaty and is considered significant as it was the first and only documented time when Europeans negotiated their presence and occupation of Aboriginal lands directly with the traditional owners.', 1835, 6, 6, NULL, NULL, NULL, 'day', '6 June 1835', 41, 'https://en.wikipedia.org/wiki/Batman''s_Treaty'),
  ('Q1785309', 'Myall Creek massacre', 'The Myall Creek massacre was the killing of at least 28 unarmed Aboriginal people in the Colony of New South Wales by eight colonists on 10 June 1838 at the Myall Creek in the north of the colony. Seven perpetrators were convicted of murder and hanged.', 1838, 6, 10, NULL, NULL, NULL, 'day', '10 June 1838', 39, 'https://en.wikipedia.org/wiki/Myall_Creek_massacre'),
  ('Q23073905', 'Waterloo Bay massacre', 'The Waterloo Bay massacre, also known as the Elliston massacre, was a clash between European settlers and Aboriginal Australians that took place on the cliffs of Waterloo Bay near Elliston, South Australia, in late May 1849. Part of the Australian frontier wars, the most recent scholarship indicates that it is likely that it resulted in the deaths of tens or scores of Aboriginal people.', 1849, 5, 17, NULL, NULL, NULL, 'day', '17 May 1849', 34, 'https://en.wikipedia.org/wiki/Waterloo_Bay_massacre'),
  ('Q2164870', 'Eureka Rebellion', 'The Eureka Rebellion was a rebellion by gold miners against the Colony of Victoria during the Victorian gold rush. It culminated in the Battle of the Eureka Stockade, which took place on 3 December 1854 at Ballarat between the rebels and colonial forces and, according to official records, resulted in 27 deaths and many injuries, the majority of casualties being rebels.', 1854, 12, 3, NULL, NULL, NULL, 'day', '3 December 1854', 58, 'https://en.wikipedia.org/wiki/Eureka_Rebellion'),
  ('Q215112', 'Second Boer War', 'The Second Boer War was a conflict fought between 1899 and 1902 between the British Empire and the Boer republics (the South African Republic and Orange Free State), triggered by the discovery of gold in the Transvaal, specifically the Witwatersrand gold fields, and the ensuing political dispute over the voting rights of British expatriates (Uitlanders). In 1877, the British annexed the bankrupt Transvaal, and the British military neutralized the regional threat of the Zulu Kingdom in 1879 in the Anglo-Zulu War.', 1899, 10, 11, 1902, 5, 31, 'day', '11 October 1899 – 31 May 1902', 79, 'https://en.wikipedia.org/wiki/Second_Boer_War'),
  ('Q2981856', 'Battle of Cocos', 'The Battle of Cocos was a single-ship action that occurred on 9 November 1914, after the Australian light cruiser HMAS Sydney, under the command of John Glossop, responded to an attack on a communications station at Direction Island by the German light cruiser SMS Emden, commanded by Karl von Müller. After the retreat of the German East Asia Squadron from Southeast Asia, Emden had remained behind to function as a commerce raider.', 1914, 11, 9, NULL, NULL, NULL, 'day', '9 November 1914', 51, 'https://en.wikipedia.org/wiki/Battle_of_Cocos'),
  ('Q156554', 'Battle of Jutland', 'The Battle of Jutland was a naval battle between Britain''s Royal Navy Grand Fleet, under Admiral Sir John Jellicoe, and the Imperial German Navy''s High Seas Fleet, under Vice-Admiral Reinhard Scheer, during the First World War. The battle unfolded in extensive manoeuvring and three main engagements from 31 May to 1 June 1916, off the North Sea coast of Denmark''s Jutland Peninsula.', 1916, 5, 31, 1916, 6, 1, 'day', '31 May 1916 – 1 June 1916', 77, 'https://en.wikipedia.org/wiki/Battle_of_Jutland'),
  ('Q79911', 'Russian Civil War', 'The Russian Civil War was a multi-party civil war in the former Russian Empire, lasting from 1917 to 1922, sparked by the overthrowing of the Russian Provisional Government in the October Revolution, as many factions vied to determine Russia''s political future. It resulted in the formation of the Russian Socialist Federative Soviet Republic and later the Soviet Union in most of its territory.', 1917, 11, 7, 1922, 10, 25, 'day', '7 November 1917 – 25 October 1922', 88, 'https://en.wikipedia.org/wiki/Russian_Civil_War'),
  ('Q1144824', 'Battle of Messines', 'The Battle of Messines (7–14 June 1917) was an attack by the British Second Army (General Sir Herbert Plumer), on the Western Front, near the village of Messines (Dutch: Mesen) in West Flanders, Belgium, during the First World War. The Nivelle Offensive in April and May had failed to achieve its more grandiose aims, had led to the demoralisation of French troops and confounded the Anglo-French strategy for 1917.', 1917, 6, 7, 1917, 6, 14, 'day', '7 June 1917 – 14 June 1917', 64, 'https://en.wikipedia.org/wiki/Battle_of_Messines_(1917)'),
  ('Q361', 'World War I', 'World War I, or the First World War (28 July 1914 – 11 November 1918), also known as the Great War, was a global conflict between two coalitions: the Allies (or Entente) and the Central Powers. One of the deadliest conflicts in history, World War I caused 15 to 22 million deaths, including those resulting from war crimes and genocides.', 1918, 11, 11, 1918, 11, 11, 'day', '11 November 1918', 100, 'https://en.wikipedia.org/wiki/World_War_I'),
  ('Q911448', 'Battle of Amiens', 'The Battle of Amiens, also known as the Third Battle of Picardy, was the opening phase of the Allied offensive which began on 8 August 1918, later known as the Hundred Days Offensive, which ultimately led to the end of World War I. Allied forces advanced over 11 kilometres (7 mi) on the first day, one of the greatest advances of the war, with Gen Henry Rawlinson''s British Fourth Army, with nine of its 19 divisions supplied by the fast-moving Australian Corps of Lt General John Monash and Canadian Corps of Lt General Arthur Currie, and Gen Marie Eugène Debeney''s French First Army playing a…', 1918, 8, 8, 1918, 8, 12, 'day', '8 August 1918 – 12 August 1918', 64, 'https://en.wikipedia.org/wiki/Battle_of_Amiens_(1918)'),
  ('Q719883', 'Statute of Westminster 1931', 'The Statute of Westminster 1931 (22 & 23 Geo. 5.', 1931, NULL, NULL, NULL, NULL, NULL, 'year', '1931', 71, 'https://en.wikipedia.org/wiki/Statute_of_Westminster_1931'),
  ('Q362', 'World War II', 'World War II, or the Second World War (1 September 1939 – 2 September 1945), was a global conflict between two coalitions: the Allies and the Axis powers. Nearly all of the world''s countries were involved, with many engaging in total war on an unprecedented scale.', 1939, 9, 1, 1945, 9, 2, 'day', '1 September 1939 – 2 September 1945', 100, 'https://en.wikipedia.org/wiki/World_War_II'),
  ('Q218678', 'North African campaign', 'The North African campaign of World War II took place in North Africa from 11 June 1940 to 13 May 1943, fought between the Allies and the Axis powers. It included campaigns in the Libyan and Egyptian deserts (Western Desert campaign, Desert War), in Morocco and Algeria (Operation Torch), and in Tunisia (Tunisia campaign).', 1940, 6, 10, 1943, 5, 16, 'day', '10 June 1940 – 16 May 1943', 75, 'https://en.wikipedia.org/wiki/North_African_campaign'),
  ('Q4564700', '1940 Brocklesby mid-air collision', 'On 29 September 1940, a mid-air collision occurred over Brocklesby, New South Wales, Australia. The accident was unusual in that the aircraft involved, two Royal Australian Air Force (RAAF) Avro Ansons of No.', 1940, 9, 29, NULL, NULL, NULL, 'day', '29 September 1940', 47, 'https://en.wikipedia.org/wiki/1940_Brocklesby_mid-air_collision'),
  ('Q58459', 'Battle between HMAS Sydney and German auxiliary cruiser Kormoran', 'On 19 November 1941, the Australian light cruiser HMAS Sydney and the German auxiliary cruiser Kormoran engaged each other in a battle off the coast of Western Australia. Sydney, with Captain Joseph Burnett commanding, and Kormoran, under Fregattenkapitän (lit. ''Frigate captain'') Theodor Detmers, encountered each other approximately 106 nautical miles (196 km; 122 mi) off Dirk Hartog Island.', 1941, 11, 19, NULL, NULL, NULL, 'day', '19 November 1941', 43, 'https://en.wikipedia.org/wiki/Sinking_of_HMAS_Sydney'),
  ('Q544090', 'Battle of Cape Matapan', 'The Battle of Cape Matapan (Greek: Ναυμαχία του Ταινάρου) was a naval battle during the Second World War between the Allies, represented by the navies of the United Kingdom and Australia, and the Royal Italian Navy, from 27 to 29 March 1941. Cape Matapan is on the south-western coast of the Peloponnesian peninsula of Greece.', 1941, 3, 27, 1941, 3, 29, 'day', '27 March 1941 – 29 March 1941', 65, 'https://en.wikipedia.org/wiki/Battle_of_Cape_Matapan'),
  ('Q696848', 'Anglo-Iraqi War', 'The Anglo-Iraqi War was a British-led Allied military campaign during the Second World War against the Kingdom of Iraq, then ruled by Rashid Ali al-Gaylani who had seized power in the 1941 Iraqi coup d''état with assistance from Germany and Italy. The campaign resulted in the downfall of Gaylani''s government, the re-occupation of Iraq by the British, and the return to power of the Regent of Iraq, Prince ''Abd al-Ilah, a British ally.', 1941, NULL, NULL, 1941, 5, 31, 'year', '1941', 70, 'https://en.wikipedia.org/wiki/Anglo-Iraqi_War'),
  ('Q207165', 'Battle of the Coral Sea', 'The Battle of the Coral Sea, from 4 to 8 May 1942, was a major naval battle between the Imperial Japanese Navy (IJN) and naval and air forces of the United States and Australia. Taking place in the Pacific Theatre of World War II, the battle was the first naval action in which the opposing fleets neither sighted nor fired upon one another, attacking over the horizon from aircraft carriers instead.', 1942, 5, 4, 1942, 5, 8, 'day', '4 May 1942 – 8 May 1942', 74, 'https://en.wikipedia.org/wiki/Battle_of_the_Coral_Sea'),
  ('Q263142', 'Battle of the Java Sea', 'The Battle of the Java Sea (Indonesian: Pertempuran Laut Jawa, Japanese: スラバヤ沖海戦, romanized: Surabaya oki kaisen, lit. ''Sea Battle off Surabaya'') was a decisive naval battle of the Pacific campaign of World War II. Allied naval forces suffered a decisive defeat at the hands of the Imperial Japanese Navy on 27 February 1942. In secondary actions over successive days, starting when the Allies'' Combined Striking Force (CSF) of two heavy cruisers, three light cruisers, and nine destroyers, led by Rear-Admiral Karel Doorman of the Royal Netherlands Navy, attempted to intercept a Japanese troop…', 1942, 2, 27, NULL, NULL, NULL, 'day', '27 February 1942', 65, 'https://en.wikipedia.org/wiki/Battle_of_the_Java_Sea'),
  ('Q296754', 'Battle of Singapore', 'Singapore was captured from the British by the Empire of Japan in February 1942 during the Second World War. The Fall or Battle of Singapore took place in the South–East Asian theatre of the Pacific War, with fighting lasting from 8 to 15 February 1942.', 1942, 2, 8, 1942, 2, 15, 'day', '8 February 1942 – 15 February 1942', 72, 'https://en.wikipedia.org/wiki/Fall_of_Singapore'),
  ('Q696557', 'Bombing of Darwin', 'On 19 February 1942, 188 carrier based & 54 land based Japanese aircraft, in two separate raids, bombed the Australian town of Darwin, ships in Darwin Harbour and the town''s two airfields in an attempt to prevent the Allies from using them as bases to contest the invasion of Timor and Java during World War II. This was the largest single attack ever mounted by a foreign power on Australia. Darwin was very lightly defended relative to the size of this attack, and the Japanese inflicted heavy losses upon Allied forces at little cost to themselves.', 1942, 2, 19, NULL, NULL, NULL, 'day', '19 February 1942', 62, 'https://en.wikipedia.org/wiki/Bombing_of_Darwin'),
  ('Q757871', 'Indian Ocean raid', 'The Indian Ocean raid (Operation C, the Third Mobile Operation in the Indian Ocean and the Battle of Ceylon in Japanese) was a sortie of the Imperial Japanese Navy (IJN) from 31 March to 10 April 1942. Japanese aircraft carriers (Admiral Chūichi Nagumo) struck Allied shipping, naval bases and airfields around British Ceylon but failed to find most of the Eastern Fleet.', 1942, 3, 31, 1942, 4, 10, 'day', '31 March 1942 – 10 April 1942', 63, 'https://en.wikipedia.org/wiki/Indian_Ocean_raid'),
  ('Q1361210', 'Battle of Christmas Island', 'The Battle of Christmas Island was a small engagement which began on 31 March 1942, during World War II. Assisted by a mutiny of soldiers of the British Indian Army against their British officers, Imperial Japanese Army troops were able to occupy Christmas Island unopposed. The United States Navy submarine Seawolf severely damaged the Imperial Japanese Navy cruiser Naka during the landings.', 1942, 3, 31, 1942, 4, 1, 'day', '31 March 1942 – 1 April 1942', 57, 'https://en.wikipedia.org/wiki/Battle_of_Christmas_Island'),
  ('Q2659473', 'Attack on Sydney Harbour', 'From 31 May to 8 June 1942, during World War II, Imperial Japanese Navy submarines made a series of attacks on the Australian cities of Sydney and Newcastle. On the night of 31 May – 1 June, three Ko-hyoteki-class midget submarines (M-14, M-21 and M-24), each with a two-member crew, entered Sydney Harbour, avoided the partially constructed Sydney Harbour anti-submarine boom net, and attempted to sink Allied warships.', 1942, 6, 8, 1942, 6, 8, 'day', '8 June 1942', 48, 'https://en.wikipedia.org/wiki/Attack_on_Sydney_Harbour'),
  ('Q16470', 'Normandy landings', 'The Normandy landings were the landing operations and associated airborne operations on 6 June 1944 of the Allied invasion of Normandy in Operation Overlord during the Second World War. Codenamed Operation Neptune and often referred to as D-Day (after the military term), it is the largest seaborne invasion in history.', 1944, 6, 6, 1944, 8, 29, 'day', '6 June 1944 – 29 August 1944', 81, 'https://en.wikipedia.org/wiki/Normandy_landings'),
  ('Q188532', 'Bretton Woods system', 'The Bretton Woods system of monetary management established the rules for commercial relations among 44 countries, including the United Kingdom, United States, Canada, European countries, and Australia, after the 1944 Bretton Woods Agreement until the Jamaica Accords in 1976. The Bretton Woods system was the first example of a fully negotiated monetary order intended to govern monetary relations among independent states.', 1944, 7, 22, NULL, NULL, NULL, 'day', '22 July 1944', 78, 'https://en.wikipedia.org/wiki/Bretton_Woods_system'),
  ('Q192660', 'Battle of Okinawa', 'The Battle of Okinawa (Japanese: 沖縄戦, Hepburn: Okinawa-sen), codenamed Operation Iceberg, was a major battle of the Pacific War fought on the island of Okinawa by the United States Army and United States Marine Corps forces against the Imperial Japanese Army. The initial invasion of Okinawa on 1 April 1945 was the largest amphibious assault in the Pacific Theater of World War II. The Kerama Islands surrounding Okinawa were preemptively captured on 26 March 1945 by the U.S. Army 77th Infantry Division.', 1945, NULL, NULL, 1945, 6, 23, 'year', '1945', 77, 'https://en.wikipedia.org/wiki/Battle_of_Okinawa'),
  ('Q665554', 'Japanese Instrument of Surrender', 'The Japanese Instrument of Surrender was the printed agreement that formalized the surrender of Japan, marking the end of hostilities in World War II. It was signed by representatives from Japan and from the Allied nations: the United States, China, the United Kingdom, the Soviet Union, Australia, Canada, France, the Netherlands, and New Zealand. The signing took place on the deck of USS Missouri in Tokyo Bay just after 09:00 Japan Standard Time (JST) and took effect at 09:25 JST on 2 September 1945.', 1945, 9, 2, NULL, NULL, NULL, 'day', '2 September 1945', 69, 'https://en.wikipedia.org/wiki/Japanese_Instrument_of_Surrender'),
  ('Q2156895', 'Borneo campaign', 'The Borneo campaign or Second Battle of Borneo was the last major Allied campaign in the South West Pacific Area during World War II to liberate Japanese-held British Borneo and Dutch Borneo. Designated collectively as Operation Oboe, a series of amphibious assaults between 1 May and 21 July 1945 were conducted by the Australian I Corps, under Lieutenant-General Leslie Morshead, against Imperial Japanese forces who had been occupying the island since late 1941 – early 1942.', 1945, NULL, NULL, 1945, 8, 15, 'year', '1945', 64, 'https://en.wikipedia.org/wiki/Borneo_campaign'),
  ('Q2354629', 'Malayan Emergency', 'The Malayan Emergency, also known as the Anti–British National Liberation War, (1948–1960) was a guerrilla war fought in Malaya between communist pro-independence fighters of the Malayan National Liberation Army (MNLA) and the military forces of the Federation of Malaya and the Commonwealth (British Empire). The MNLA fought to win Malayan independence from the British Empire and to establish a communist state, while the Malayan Federation and Commonwealth forces fought to protect British economic and colonial interests and combat communism.', 1948, 6, 16, 1960, 7, 12, 'day', '16 June 1948 – 12 July 1960', 68, 'https://en.wikipedia.org/wiki/Malayan_Emergency'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q82542', 'Tet Offensive', 'The Tet Offensive was both a major escalation and one of the largest military campaigns of the Vietnam War. The North Vietnamese People''s Army of Vietnam (PAVN) and the Viet Cong (VC) launched a surprise attack on 30 and 31 January 1968 against the forces of the South Vietnamese Army of the Republic of Vietnam (ARVN), the United States Armed Forces and their allies, targeting military and civilian command and control centers throughout South Vietnam.', 1968, 1, 30, 1968, 9, 23, 'day', '30 January 1968 – 23 September 1968', 72, 'https://en.wikipedia.org/wiki/Tet_Offensive'),
  ('Q8740', 'Vietnam War', 'The Vietnam War (c. 1955 – 30 April 1975) was an armed conflict in Vietnam, Laos, and Cambodia fought between North Vietnam (Democratic Republic of Vietnam) and South Vietnam (Republic of Vietnam) and their allies. North Vietnam was supported by the Soviet Union and China, while South Vietnam was supported by the United States and other anti-communist nations.', 1975, 4, 30, 1975, 4, 30, 'day', '30 April 1975', 97, 'https://en.wikipedia.org/wiki/Vietnam_War'),
  ('Q4867015', 'Basic Treaty of Friendship and Cooperation', 'The Basic Treaty of Friendship and Cooperation (nicknamed the NARA Treaty) was a treaty signed between Australia and Japan that established a broad framework of principles to guide and enhance future bilateral relations in the political, economic, cultural and other fields. The treaty is historically significant because it is the first comprehensive treaty of its kind for both countries alike, containing both symbolic and practical provisions which acknowledged indispensable economic ties.', 1976, 6, 16, NULL, NULL, NULL, 'day', '16 June 1976', 26, 'https://en.wikipedia.org/wiki/Basic_Treaty_of_Friendship_and_Cooperation'),
  ('Q3088733', 'Australia–France border', 'The Australia–France Marine Delimitation Agreement is a 1982 treaty between Australia and France which establishes ocean borders between Australian territories and French territories. The treaty was signed in Melbourne on 4 January 1982.', 1982, NULL, NULL, NULL, NULL, NULL, 'year', '1982', 26, 'https://en.wikipedia.org/wiki/Australia%E2%80%93France_Marine_Delimitation_Agreement'),
  ('Q4585341', '1989 Newcastle earthquake', 'The 1989 Newcastle earthquake was an intraplate earthquake that occurred in Newcastle, New South Wales, on Thursday 28 December. The shock measured 5.6 on the Richter scale and was one of Australia''s most serious natural disasters, killing 13 people and injuring more than 160.', 1989, 12, 28, NULL, NULL, NULL, 'day', '28 December 1989', 43, 'https://en.wikipedia.org/wiki/1989_Newcastle_earthquake'),
  ('Q37643', 'Gulf War', 'The Gulf War was an armed conflict between Iraq and a 42-country coalition led by the United States in response to the Iraqi invasion of Kuwait on 2 August 1990. The coalition''s efforts were carried out in two phases: Operation Desert Shield, which marked the military buildup in the Persian Gulf region from August 1990 to January 1991; and Operation Desert Storm, which began with the bombing campaign against Iraq on 17 January and continued until the liberation of Kuwait on 28 February.', 1990, 8, 2, 1991, 2, 28, 'day', '2 August 1990 – 28 February 1991', 90, 'https://en.wikipedia.org/wiki/Gulf_War'),
  ('Q2559142', 'Australian republic referendum', 'The Australian republic referendum held on 6 November 1999 was a two-question referendum to amend the Constitution of Australia. The first question asked whether Australia should become a republic, under a bi-partisan appointment model where the president would be appointed by the federal parliament with a two-thirds majority.', 1999, 11, 6, NULL, NULL, NULL, 'day', '6 November 1999', 55, 'https://en.wikipedia.org/wiki/1999_Australian_republic_referendum'),
  ('Q182865', 'War in Afghanistan (2001–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2001, 10, 7, 2021, 8, 30, 'day', '7 October 2001 – 30 August 2021', 84, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2001%E2%80%932021)'),
  ('Q1476042', 'Operation Anaconda', 'Operation Anaconda or the Battle of Shah-i-Kot was a military operation that took place in early March 2002 as part of the war in Afghanistan. CIA paramilitary officers, working with their allies, attempted to destroy al-Qaeda and Taliban forces.', 2002, NULL, NULL, 2002, 3, 18, 'year', '2002', 59, 'https://en.wikipedia.org/wiki/Operation_Anaconda'),
  ('Q107802', '2003 invasion of Iraq', 'The 2003 invasion of Iraq was the first stage of the Iraq War. The invasion began on 20 March 2003 and lasted just over one month, including 26 days of major combat operations.', 2003, 3, 20, 2003, 5, 1, 'day', '20 March 2003 – 1 May 2003', 74, 'https://en.wikipedia.org/wiki/2003_invasion_of_Iraq'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q3562612', 'Qantas Flight 72', 'Qantas Flight 72 (QF72) was a scheduled flight from Singapore Changi Airport to Perth Airport by an Airbus A330. On 7 October 2008, the flight made an emergency landing at Learmonth Airport near the town of Exmouth, Western Australia, following an in-flight upset that included a pair of sudden, uncommanded pitch-down manoeuvres that caused severe injuries—including fractures, lacerations and spinal injuries—to several of the passengers and crew.', 2008, 10, 7, NULL, NULL, NULL, 'day', '7 October 2008', 50, 'https://en.wikipedia.org/wiki/Qantas_Flight_72'),
  ('Q4216844', '2010 Kalgoorlie-Boulder earthquake', 'The 2010 Kalgoorlie–Boulder earthquake was a 5.2 Mw earthquake that occurred near the city of Kalgoorlie–Boulder, Western Australia on 20 April 2010, at approximately 8:17 am WST. The earthquake caused major damage to the historic buildings in Kalgoorlie–Boulder. Its epicenter was approximately 10 km (6.2 mi) southwest of Kalgoorlie, at a depth of 10 km (6.2 mi).', 2010, 4, 20, NULL, NULL, NULL, 'day', '20 April 2010', 37, 'https://en.wikipedia.org/wiki/2010_Kalgoorlie%E2%80%93Boulder_earthquake'),
  ('Q333374', 'Early 2011 Victorian floods', 'High intensity rainfall between 12–14 January 2011 caused major flooding across much of the western and central parts of the Australian state of Victoria. Several follow-up heavy rainfall events including Tropical Low Yasi caused repeated flash flooding in affected areas in early February in many of the communities affected by January''s floods.', 2011, 1, 12, NULL, NULL, NULL, 'day', '12 January 2011', 34, 'https://en.wikipedia.org/wiki/2011_Victoria_floods'),
  ('Q837833', '2010–2011 Queensland floods', 'The 2010–2011 Queensland floods were a series of major floods that affected much of Queensland, Australia, between December 2010 and January 2011. Prolonged and extensive rainfall fell across large areas of the state on catchments already saturated by a strong La Niña event, following the wettest December on record for Queensland.', 2011, 1, 26, NULL, NULL, NULL, 'day', '26 January 2011', 60, 'https://en.wikipedia.org/wiki/2010%E2%80%932011_Queensland_floods'),
  ('Q4825271', 'Australia–China Free Trade Agreement', 'The China–Australia Free Trade Agreement (ChAFTA) is a bilateral free trade agreement (FTA) between the governments of Australia and China. Since negotiations began, 21 negotiating rounds have been completed.', 2015, NULL, NULL, NULL, NULL, NULL, 'year', '2015', 34, 'https://en.wikipedia.org/wiki/China%E2%80%93Australia_Free_Trade_Agreement'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q106175826', 'March 2021 Australian floods', 'Extreme rainfall on the east coast of Australia beginning on 18 March 2021 led to widespread flooding in New South Wales, affecting regions from the North Coast to the Sydney metropolitan area in the south. Suburbs of Sydney experienced the worst flooding in 60 years, and the events were described by NSW Premier Gladys Berejiklian as "one in 100-year" flooding.', 2021, 3, 18, 2021, 3, 29, 'day', '18 March 2021 – 29 March 2021', 34, 'https://en.wikipedia.org/wiki/2021_eastern_Australia_floods'),
  ('Q108647613', '2021 Mansfield earthquake', 'An earthquake struck approximately 53 kilometres SSE of the town of Mansfield (in the vicinity of the township of Woods Point), in the Victorian Alps of Australia on 22 September 2021, at 09:15 local time. The earthquake measured 5.9 on the moment magnitude scale.', 2021, 9, 22, NULL, NULL, NULL, 'day', '22 September 2021', 47, 'https://en.wikipedia.org/wiki/2021_Mansfield_earthquake'),
  ('Q112947091', '2022 New South Wales floods', 'Heavy flooding broke out in the Central Coast and Sydney areas of New South Wales, Australia, beginning in early July 2022. Around 85,000 people were displaced by the flooding or requested to leave their homes by authorities.', 2022, NULL, NULL, 2022, 7, 8, 'year', '2022', 39, 'https://en.wikipedia.org/wiki/2022_New_South_Wales_floods'),
  ('Q121840647', 'Rubiales affair', 'The Rubiales case (Spanish: caso Rubiales) refers to the behaviour of and the events that followed the actions of Luis Rubiales, the president of the Royal Spanish Football Federation (RFEF), during the 2023 FIFA Women''s World Cup final. After allegations of inappropriate behavior during the 2023 FIFA Women''s World Cup final on 20 August 2023, Rubiales'' response was perceived by critics to have exacerbated the situation in the days following the tournament, and to have exacerbated the controversy.', 2023, 8, 20, NULL, NULL, NULL, 'day', '20 August 2023', 37, 'https://en.wikipedia.org/wiki/Rubiales_case'),
  ('Q137383251', '2025 Bondi Beach shooting', 'On 14 December 2025, an antisemitic and Islamic State (IS)–inspired terrorist attack occurred at the Archer Park area of Bondi Beach in Sydney, New South Wales, Australia, during a celebration of the Jewish holiday of Hanukkah attended by around 1,000 people. Sajid Akram and his son, Naveed Akram, allegedly shot dead 15 people, aged between 10 and 87, and injured forty others, including two police officers.', 2025, 12, 14, NULL, NULL, NULL, 'day', '14 December 2025', 72, 'https://en.wikipedia.org/wiki/Bondi_Beach_shooting');
